files.content:
'use client';

// The documents screen: the workspace's Library is the list (`ListDetail`: beside the file on a wide screen, one pane at a time on a phone);
// the chosen file opens in the same viewer the Library uses (editable where it edits); its Revisions sit beside it. An older revision opens
// read-only in the artifact panel (the viewer that shows a pinned version), and « Latest » returns to the editable file. Every file and
// every version is read through the one `revisionProvider` the host binds (the files guide). Host concern: Pi has no document screens.
import { useEffect, useMemo, useState } from 'react';
import { createFileTreeController } from '@hachej/boring-ui-kit/file-tree';
import type { FileTreeController } from '@hachej/boring-ui-kit/file-tree';
import { FileTreeView } from '../file-tree/file-tree';
import type { RevisionProvider } from '@hachej/boring-files/revision';
import { mediaTypeOf, viewerKindOf } from '@hachej/boring-files/file-types';
import { ListDetail } from '../app-shell/list-detail';
import { ArtifactPanel } from '../pi-app/artifact-panel';
import type { ArtifactDescriptor } from '../pi-chat/artifact';
import type { CustomViewers, ViewerOptions } from '../pi-app/artifact-panel';
import { FileViewer } from '../pi-app/file-viewer';
import { ViewerFrame } from '../viewers/viewer-frame';
import { Revisions } from './revisions';
import type { DocumentsLabels } from './documents-labels';
import { documentsLabels, DocumentsWords } from './words';
import type { DocumentsLocale } from './words';

export interface DocumentsProps {
  /** The workspace's revision provider (the files guide's `connectRevisionProvider`, or a host's own binding). Borrowed: the host disposes it. */
  readonly provider: RevisionProvider;
  readonly locale?: DocumentsLocale | undefined;
  /** The block's own words, over `documentsLabels` (the viewers' words follow `locale`). */
  readonly labels?: Partial<DocumentsLabels> | undefined;
  /** Host viewers by kind, as for the Library (for example a canvas). */
  readonly viewers?: CustomViewers | undefined;
  readonly share?: ViewerOptions['share'];
}

/** The workspace's change feed as a counter: it moves on every change, so the listings and the revisions are read again. */
function useWorkspaceVersion(provider: RevisionProvider): number {
  const [version, setVersion] = useState(0);
  useEffect(() => {
    if (!provider.changes) return undefined;
    const abort = new AbortController();
    void (async () => {
      try { for await (const change of provider.changes!({ signal: abort.signal })) { void change; setVersion(current => current + 1); } } catch { /* the binding ended the feed: the listings stay as they are */ }
    })();
    return () => abort.abort();
  }, [provider]);
  return version;
}

/** The Library's tree over the provider: created and disposed with the binding, read again when the workspace changes. */
function useFileTree(provider: RevisionProvider, version: number): FileTreeController | undefined {
  const [tree, setTree] = useState<FileTreeController>();
  useEffect(() => {
    const next = createFileTreeController({ revisionProvider: provider });
    setTree(next);
    void next.refresh();
    return () => next.dispose();
  }, [provider]);
  useEffect(() => {
    if (!tree || version === 0) return;
    const { query, expanded } = tree.getSnapshot();
    if (query) void tree.search(query);
    else for (const directory of ['', ...expanded]) void tree.refresh(directory);
  }, [tree, version]);
  return tree;
}

/** An older revision of a file, read-only. Text, Markdown and HTML have a read-only view of a pinned version; other kinds do not here. */
function OlderVersion({ provider, path, revision, options, unsupported, onLatest, onClose }: {
  readonly provider: RevisionProvider;
  readonly path: string;
  readonly revision: string;
  readonly options: ViewerOptions;
  readonly unsupported: string;
  readonly onLatest: () => void;
  readonly onClose: () => void;
}) {
  const name = path.split('/').pop() || path;
  const kind = viewerKindOf(path);
  const type = kind === 'markdown' ? 'markdown' : kind === 'html' ? 'html' : kind === 'text' ? 'code' : undefined;
  if (type === undefined) return <ViewerFrame title={name} onClose={onClose}><p role="status" className="m-0 p-4 text-sm text-muted-foreground">{unsupported}</p></ViewerFrame>;
  const artifact: ArtifactDescriptor = { schema: 'boring.artifact', version: 1, title: name, type, mediaType: mediaTypeOf(path), target: provider.locate(path), revision };
  return <ArtifactPanel active={{ descriptor: artifact, follow: false }} versions={[]} options={options} onSelect={onLatest} onClose={onClose} />;
}

function DocumentDetail({ provider, path, version, options, labels, locale, older, onOpenRevision, onClose }: {
  readonly provider: RevisionProvider;
  readonly path: string;
  readonly version: number;
  readonly options: ViewerOptions;
  readonly labels: DocumentsLabels;
  readonly locale: DocumentsLocale;
  /** The older revision on show, `undefined` for the latest. */
  readonly older: string | undefined;
  readonly onOpenRevision: (revision: string | undefined) => void;
  readonly onClose: () => void;
}) {
  return <div data-testid="documents-detail" className="flex h-full min-h-0 flex-col md:flex-row [&_button]:pointer-coarse:min-h-11 [&_button]:pointer-coarse:min-w-11">
    <div className="flex min-h-0 min-w-0 flex-1 flex-col">
      {older === undefined
        ? <FileViewer path={path} locator={provider.locate(path)} options={options} onClose={onClose} />
        : <OlderVersion provider={provider} path={path} revision={older} options={options} unsupported={labels.unsupportedPreview} onLatest={() => onOpenRevision(undefined)} onClose={onClose} />}
    </div>
    <aside className="flex max-h-[40%] min-h-0 shrink-0 flex-col overflow-y-auto border-t border-border md:max-h-none md:w-72 md:border-t-0 md:border-l">
      <Revisions provider={provider} path={path} version={version} selected={older} locale={locale} labels={labels} onOpen={onOpenRevision} />
    </aside>
  </div>;
}

export function Documents({ provider, locale, labels: given, viewers, share }: DocumentsProps) {
  const labels = documentsLabels(locale, given);
  const language: DocumentsLocale = locale === 'fr' ? 'fr' : 'en';
  const version = useWorkspaceVersion(provider);
  const tree = useFileTree(provider, version);
  const [path, setPath] = useState<string>();
  // An older revision of the file on show (`undefined`: the latest, editable as the Library opens it).
  const [pinned, setPinned] = useState<{ readonly path: string; readonly revision: string }>();
  const options = useMemo<ViewerOptions>(() => ({ client: provider, identity: provider.identity, ...(viewers ? { viewers } : {}), ...(share ? { share } : {}) }), [provider, viewers, share]);
  // The Library's buttons are at least 44px on a coarse pointer (a touch screen); the tree itself is the file-tree item's, unchanged.
  const list = tree ? <div className="min-h-0 [&_button]:pointer-coarse:min-h-11 [&_button]:pointer-coarse:min-w-11">
    <FileTreeView controller={tree} onOpen={next => { setPath(next); setPinned(undefined); }} selectedPath={path} locale={language} upload={false} history={false} />
  </div> : null;
  const older = path !== undefined && pinned?.path === path ? pinned.revision : undefined;
  // `null` (nothing chosen) is what lets a phone show the list alone: ListDetail stacks the detail only when there is one.
  const detail = path === undefined ? null
    : <DocumentDetail key={path} provider={provider} path={path} version={version} options={options} labels={labels} locale={language} older={older}
      onOpenRevision={revision => setPinned(revision === undefined || path === undefined ? undefined : { path, revision })}
      onClose={() => { setPath(undefined); setPinned(undefined); }} />;
  return <DocumentsWords locale={locale}>
    <ListDetail list={list} detail={detail} onBack={() => { setPath(undefined); setPinned(undefined); }} />
  </DocumentsWords>;
}

'use client';

// One document over the app, for « Voir la fiche »: the host sets `path` from its own handler (for example its `onOpenSpec`) and clears it in
// `onClose`. The sheet is a full-screen view of the shell (`useShellLayer`): it closes the agent layers when it opens, and Back closes it
// first. The file is the same viewer the Library opens (editable where the viewer edits). `onShowAll` adds « Toutes les fiches ».
import { useEffect, useRef } from 'react';
import { Drawer, DrawerContent, DrawerTitle } from '@/components/ui/drawer';
import { useShellLayer } from '../app-shell/shell-layer';
import { useExclusiveSheet } from '../app-shell/sheet';
import { FileViewer } from '../pi-app/file-viewer';
import type { CustomViewers, ViewerOptions } from '../pi-app/artifact-panel';
import type { RevisionProvider } from '@hachej/boring-files/revision';
import { cn } from '../utils/utils';
import { documentsLabels, DocumentsWords } from './words';
import type { DocumentsLocale } from './words';
import type { DocumentsLabels } from './documents-labels';

export interface DocumentSheetProps {
  readonly provider: RevisionProvider;
  /** The workspace path of the document on show; `undefined` closes the sheet. */
  readonly path: string | undefined;
  /** Called when the person closes the sheet (its close button, a swipe, Back): the host clears `path`. */
  readonly onClose: () => void;
  /** Adds « Toutes les fiches » to the sheet. The sheet closes first, then this runs. */
  readonly onShowAll?: (() => void) | undefined;
  readonly locale?: DocumentsLocale | undefined;
  readonly labels?: Partial<DocumentsLabels> | undefined;
  /** Host viewers by kind, as for the Library (for example a canvas). */
  readonly viewers?: CustomViewers | undefined;
  readonly share?: ViewerOptions['share'];
  readonly className?: string | undefined;
}

/** The sheet's name in the shell's layers: one sheet of this kind at a time. */
const LAYER = 'document';

export function DocumentSheet({ provider, path, onClose, onShowAll, locale, labels: given, viewers, share, className }: DocumentSheetProps) {
  const shown = path !== undefined;
  const { open, close, isOpen } = useShellLayer(LAYER);
  const labels = documentsLabels(locale, given);
  // The host's `path` decides whether the sheet is on show; a close from the sheet itself (Back, swipe, its buttons) reports to the host.
  useEffect(() => { if (shown) open(); else close(); }, [shown, open, close]);
  useExclusiveSheet(isOpen, close);
  const wasOpen = useRef(false);
  useEffect(() => {
    if (shown && wasOpen.current && !isOpen) onClose();
    wasOpen.current = isOpen;
  }, [isOpen, shown, onClose]);
  const title = path === undefined ? labels.sheetTitle : path.split('/').pop() || path;
  return <DocumentsWords locale={locale}>
    <Drawer open={isOpen} onOpenChange={next => { if (!next) close(); }} showSwipeHandle swipeDirection="down">
      <DrawerContent data-testid="document-sheet" className={cn('app-shell h-[92dvh] max-h-[92dvh] pb-[env(safe-area-inset-bottom)]', className)}>
        {/* The title is for assistive technology: the viewer's own bar shows the file name. */}
        <DrawerTitle className="sr-only">{title}</DrawerTitle>
        {onShowAll && <div className="flex shrink-0 justify-end px-3 pt-1 pb-2">
          <button type="button" data-testid="document-sheet-all" onClick={() => { close(); onShowAll(); }}
            className="inline-flex min-h-11 shrink-0 items-center rounded-lg border border-border bg-background px-3 text-sm outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring/60 md:min-h-8 md:text-xs">{labels.allDocuments}</button>
        </div>}
        <div className="flex min-h-0 flex-1 flex-col overflow-hidden [&_button]:pointer-coarse:min-h-11 [&_button]:pointer-coarse:min-w-11">
          {path !== undefined && <FileViewer key={path} path={path} locator={provider.locate(path)}
            options={{ client: provider, identity: provider.identity, ...(viewers ? { viewers } : {}), ...(share ? { share } : {}) }} onClose={close} />}
        </div>
      </DrawerContent>
    </Drawer>
  </DocumentsWords>;
}

'use client';

// The revisions of one file: what the workspace's history retains for it (`provider.history`, newest first), each with when it was saved and
// who wrote it (`source`). Choosing an older one opens it read-only (the documents screen shows that revision); the newest opens the latest.
import { useEffect, useState } from 'react';
import type { RevisionProvider, SavedRevision } from '@hachej/boring-files/revision';
import { cn } from '../utils/utils';
import type { DocumentsLabels } from './documents-labels';

/** The retained revisions of `path`, reloaded when `version` changes (the workspace's change feed moved). `undefined` until the first read. */
export function useRevisions(provider: RevisionProvider, path: string, version: number): { readonly path: string; readonly saves: readonly SavedRevision[] } | undefined {
  const [state, setState] = useState<{ readonly path: string; readonly saves: readonly SavedRevision[] }>();
  useEffect(() => {
    const abort = new AbortController();
    const save = (saves: readonly SavedRevision[]) => { if (!abort.signal.aborted) setState({ path, saves }); };
    provider.history(path, abort.signal).then(save, () => save([]));
    return () => abort.abort();
  }, [provider, path, version]);
  return state;
}

/** When a revision was saved, in the page's language; `savedAt` 0 means the journal did not record a time. */
export function whenSaved(savedAt: number, locale: string, unknown: string): string {
  if (!savedAt) return unknown;
  return new Date(savedAt).toLocaleString(locale === 'fr' ? 'fr-FR' : 'en-GB', { dateStyle: 'medium', timeStyle: 'short' });
}

/** The panel's list: one row per retained revision, newest first. The newest row is the latest; an older one is opened read-only. */
export function Revisions({ provider, path, version, selected, locale, labels, onOpen }: {
  readonly provider: RevisionProvider;
  readonly path: string;
  /** Bumped when the workspace's change feed moves, so the list is read again. */
  readonly version: number;
  /** The revision on show when it is an older one (`undefined`: the latest). */
  readonly selected: string | undefined;
  readonly locale: string;
  readonly labels: DocumentsLabels;
  /** Opens an older revision read-only; `undefined` opens the latest. */
  readonly onOpen: (revision: string | undefined) => void;
}) {
  const state = useRevisions(provider, path, version);
  const saves = state?.path === path ? state.saves : undefined;
  return <section data-testid="revisions" aria-label={labels.revisions} className="flex min-h-0 flex-col">
    <h2 className="m-0 px-3 py-2 text-sm font-semibold">{labels.revisions}</h2>
    {saves === undefined ? <p role="status" className="m-0 px-3 pb-3 text-sm text-muted-foreground">{labels.revisionsLoading}</p>
      : saves.length === 0 ? <p role="status" className="m-0 px-3 pb-3 text-sm text-muted-foreground">{labels.noRevisions}</p>
      : <ol className="m-0 min-h-0 list-none overflow-y-auto p-1">
        {saves.map((save, index) => {
          const current = index === 0;
          const on = current ? selected === undefined : selected === save.revision;
          const when = whenSaved(save.savedAt, locale, labels.unknownTime);
          const who = save.source ? labels.savedBy[save.source] : labels.savedBy.observed;
          return <li key={save.revision}>
            <button type="button" data-testid="revision-item" data-revision={save.revision} data-current={current ? 'true' : undefined}
              aria-current={on ? 'true' : undefined} aria-label={labels.openRevision(when)} onClick={() => onOpen(current ? undefined : save.revision)}
              className={cn('flex min-h-11 w-full flex-col items-start gap-0.5 rounded-md px-2 py-1.5 text-left text-sm outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring/60',
                on && 'bg-accent')}>
              <span className="font-medium">{current ? labels.latest : when}</span>
              <span className="text-xs text-muted-foreground">{current ? `${when}, ${who}` : who} · {labels.revisionId} {save.revision.slice(0, 8)}</span>
            </button>
          </li>;
        })}
      </ol>}
  </section>;
}

'use client';

// The words the documents block shows: its own, and the viewers' (the pi-app labels the file viewer and the artifact panel read). One
// locale for both: `fr` takes the French sets, anything else English, and a `labels` object overrides any word of the block's own.
import type { ReactNode } from 'react';
import { defaultAppIcons, defaultAppLabels, AppTextProvider } from '../pi-app/app-labels';
import { frenchAppLabels } from '../pi-app/app-labels-fr';
import { defaultDocumentsLabels, frenchDocumentsLabels } from './documents-labels';
import type { DocumentsLabels } from './documents-labels';

export type DocumentsLocale = 'en' | 'fr';

/** The block's own words for `locale`, with the host's overrides. */
export function documentsLabels(locale: DocumentsLocale | undefined, given: Partial<DocumentsLabels> | undefined): DocumentsLabels {
  return { ...(locale === 'fr' ? frenchDocumentsLabels : defaultDocumentsLabels), ...given };
}

/** Provides the viewers' words for `locale` to the file viewer and the artifact panel below it. */
export function DocumentsWords({ locale, children }: { readonly locale: DocumentsLocale | undefined; readonly children: ReactNode }) {
  const labels = locale === 'fr' ? frenchAppLabels : defaultAppLabels;
  return <AppTextProvider value={{ labels, icons: defaultAppIcons }}>{children}</AppTextProvider>;
}

/*
 * The words of the documents block as plain data: its own (the Library's title, the revisions panel, the sheet) in English and French. The
 * viewers it composes take their words from the pi-app block (`defaultAppLabels` / `frenchAppLabels`), which `Documents` provides.
 */
/** Who wrote a revision, as the history reports it. */
export type SavedByKind = 'publish' | 'agent' | 'observed';

export const defaultDocumentsLabels = {
  revisions: 'Revisions',
  noRevisions: 'No saved revisions yet.',
  revisionsLoading: 'Loading revisions…',
  latest: 'Latest',
  openRevision: (when: string) => `Open the version saved ${when}`,
  savedBy: { publish: 'saved', agent: 'written by the agent', observed: 'found in the workspace' } as Record<SavedByKind, string>,
  unknownTime: 'time unknown',
  revisionId: 'Revision',
  unsupportedPreview: 'Older versions of this kind have no preview here.',
  allDocuments: 'All documents',
  sheetTitle: 'Document',
};

export type DocumentsLabels = typeof defaultDocumentsLabels;

export const frenchDocumentsLabels: DocumentsLabels = {
  revisions: 'Versions',
  noRevisions: 'Aucune version enregistrée pour l’instant.',
  revisionsLoading: 'Chargement des versions…',
  latest: 'Dernière',
  openRevision: (when: string) => `Ouvrir la version enregistrée ${when}`,
  savedBy: { publish: 'enregistrée', agent: 'écrite par l’agent', observed: 'trouvée dans l’espace de travail' },
  unknownTime: 'date inconnue',
  revisionId: 'Version',
  unsupportedPreview: 'Les anciennes versions de ce type ne s’affichent pas ici.',
  allDocuments: 'Toutes les fiches',
  sheetTitle: 'Fiche',
};
